// Read-only, bounded native PlayerDamagedActor receipts. No input, effects,
// modifiers, RNG, damage calls or saved-record writers. Like Bench, the [Hook]
// stays registered in its script context; an active-task gate is detached first
// on every terminal path. No Actor, DamageInfo or UnitPtr handles are retained.
namespace GameLab
{
    const uint QA_DAMAGE_EVENT_CAP = 256;
    const uint QA_DAMAGE_EVENT_CHUNK = 4;

    string QADamageTargetSnapshot(int unitId)
    {
        auto unit = g_scene.GetUnit(unitId);
        Actor@ actor = null;
        if (unit.IsValid() && !unit.IsDestroyed())
            @actor = cast<Actor>(unit.GetScriptBehavior());
        Json j;
        j.Int("unit", unitId).Bool("valid", actor !is null);
        if (actor !is null)
        {
            int maxHp = actor.GetMaxHp();
            vec2 pos = xy(unit.GetPosition());
            j.Str("name", unit.GetDebugName()).Str("behavior", Reflect::GetTypeName(actor))
                .Bool("dead", actor.IsDead()).Int("hpMax", maxHp)
                .Raw("hpFraction", formatFloat(actor.GetHealth(), "", 0, 9))
                .Raw("hpExact", formatFloat(double(actor.GetHealth()) * double(maxHp), "", 0, 9))
                .Raw("x", formatFloat(pos.x, "", 0, 9)).Raw("y", formatFloat(pos.y, "", 0, 9))
                .Bool("composite", cast<CompositeActorBehavior>(actor) !is null);
        }
        return j.Close();
    }

    class QADamageEventTask : QueuedTasks::UpdatingTask
    {
        string m_tag, m_command, m_level, m_class, m_ownerName;
        Guid m_ownerGuid;
        uint m_ownerKey;
        int m_ownerUnit, m_start, m_startFrame, m_requested, m_elapsed = 0, m_frames = 0, m_maxDt = 0;
        int m_hooks = 0, m_ownerHooks = 0, m_filteredOwner = 0, m_filteredSkill = 0, m_filteredTarget = 0;
        int m_invalid = 0, m_accepted = 0, m_dropped = 0;
        bool m_finished = false, m_metadataLost = false;
        array<uint> m_skills;
        array<string> m_names, m_skillRows, m_initialTargets, m_rows;
        array<int> m_targets;

        bool OwnerCurrent()
        {
            auto rec = GetLocalPlayerRecord();
            auto plr = GetLocalPlayer();
            return rec !is null && plr !is null && rec.local && !rec.IsDead()
                && rec.id == m_ownerGuid && rec.uniqueKey == m_ownerKey
                && rec.name == m_ownerName
                && plr.m_unit.IsValid() && !plr.m_unit.IsDestroyed() && plr.m_unit.GetId() == m_ownerUnit
                && rec.playerClass !is null && rec.playerClass.m_id == m_class
                && GetCurrentLevelFilename() == m_level;
        }

        void Finish(const string &in state, const string &in reason)
        {
            if (m_finished)
                return;
            m_finished = true;
            // Detach BEFORE snapshotting or emitting; a later queued update of a
            // stopped task cannot detach a newly accepted observer.
            if (g_qaDamageEvents is this)
                @g_qaDamageEvents = null;
            int now = int(g_scene.GetTime());
            array<string> finalTargets;
            for (uint i = 0; i < m_targets.length(); i++)
                finalTargets.insertLast(QADamageTargetSnapshot(m_targets[i]));
            string finalState = state, finalReason = reason;
            if (RawArray(finalTargets).length() > 3000)
            {
                m_metadataLost = true;
                finalTargets.resize(0);
                finalState = "aborted";
                finalReason = "final-snapshot-byte-bound";
            }
            uint parts = max(uint(1), (m_rows.length() + QA_DAMAGE_EVENT_CHUNK - 1) / QA_DAMAGE_EVENT_CHUNK);
            array<Json@> output;
            for (uint part = 0; part < parts; part++)
            {
                array<string> rows;
                for (uint i = part * QA_DAMAGE_EVENT_CHUNK; i < m_rows.length() && i < (part + 1) * QA_DAMAGE_EVENT_CHUNK; i++)
                    rows.insertLast(m_rows[i]);
                Json j;
                j.Str("ev", "damageevents").Int("version", 1).Str("id", m_command).Str("tag", m_tag)
                    .Str("state", finalState).Str("reason", finalReason).Bool("detached", g_qaDamageEvents is null)
                    .Int("part", part).Int("parts", parts).Int("rowCap", QA_DAMAGE_EVENT_CAP).Int("chunk", QA_DAMAGE_EVENT_CHUNK)
                    .Int("stored", m_rows.length()).Int("accepted", m_accepted).Int("dropped", m_dropped)
                    .Bool("truncated", m_dropped > 0 || m_metadataLost).Bool("metadataLost", m_metadataLost)
                    .Int("hooks", m_hooks).Int("ownerHooks", m_ownerHooks)
                    .Int("filteredOwner", m_filteredOwner).Int("filteredSkill", m_filteredSkill)
                    .Int("filteredTarget", m_filteredTarget).Int("invalid", m_invalid)
                    .Int("start", m_start).Int("end", now).Int("requested", m_requested).Int("elapsed", m_elapsed)
                    .Int("frames", m_frames).Int("maxDt", m_maxDt).Int("startFrame", m_startFrame).Int("endFrame", g_frames)
                    .Str("level", m_level).Int("ownerUnit", m_ownerUnit).Raw("ownerKey", "" + m_ownerKey)
                    .Str("ownerClass", m_class).Str("ownerName", m_ownerName)
                    .Str("stage", "native Player.DamagedActor after PlayerBase.DamagedActor; callback-time HP, not post-debit or settled pools")
                    .Raw("skills", RawArray(m_skillRows)).Raw("initialTargets", RawArray(m_initialTargets))
                    .Raw("finalTargets", RawArray(finalTargets)).Raw("rows", RawArray(rows));
                if (j.Close().length() > EMIT_MAX)
                {
                    // Preflight EVERY part before emitting any. The generic
                    // Emit guard would otherwise replace an oversized event
                    // with an uncorrelatable short failure. Report this task's
                    // explicit loss/abort instead; consumers must reject it.
                    Json failed;
                    Emit(failed.Str("ev", "damageevents").Int("version", 1).Str("id", m_command).Str("tag", m_tag)
                        .Str("state", "aborted").Str("reason", "serialized-payload-bound")
                        .Bool("detached", g_qaDamageEvents is null).Int("part", 0).Int("parts", 1)
                        .Int("stored", 0).Int("accepted", m_accepted).Int("dropped", m_accepted)
                        .Bool("truncated", true).Bool("metadataLost", true).Int("end", now));
                    return;
                }
                output.insertLast(j);
            }
            for (uint i = 0; i < output.length(); i++)
                Emit(output[i]);
        }

        void Record(Player@ player, Actor@ actor, DamageInfo@ di)
        {
            if (m_finished)
                return;
            if (!OwnerCurrent())
            {
                Finish("aborted", "owner-class-actor-or-level-changed");
                return;
            }
            m_hooks++;
            if (player is null || player.m_record is null || !player.m_record.local
                || player.m_record.id != m_ownerGuid || player.m_record.uniqueKey != m_ownerKey
                || !player.m_unit.IsValid() || player.m_unit.IsDestroyed() || player.m_unit.GetId() != m_ownerUnit)
            {
                m_filteredOwner++;
                return;
            }
            m_ownerHooks++;
            if (actor is null || di is null || !actor.m_unit.IsValid() || actor.m_unit.IsDestroyed())
            {
                m_invalid++;
                return;
            }
            int skill = -1;
            for (uint i = 0; i < m_skills.length(); i++)
                if (di.Weapon == m_skills[i])
                    skill = int(i);
            if (skill < 0)
            {
                m_filteredSkill++;
                return;
            }
            int targetId = actor.m_unit.GetId();
            bool selected = false;
            for (uint i = 0; i < m_targets.length(); i++)
                if (targetId == m_targets[i])
                    selected = true;
            if (!selected)
            {
                m_filteredTarget++;
                return;
            }
            int index = m_accepted++;
            if (m_rows.length() >= QA_DAMAGE_EVENT_CAP)
            {
                m_dropped++;
                return;
            }
            auto liveSkill = player.GetSkill(di.Weapon);
            bool attackerValid = di.Attacker !is null && di.Attacker.m_unit.IsValid() && !di.Attacker.m_unit.IsDestroyed();
            Json j;
            j.Int("index", index).Int("now", int(g_scene.GetTime())).Int("frame", g_frames).Int("taskElapsed", m_elapsed)
                .Int("ownerUnit", m_ownerUnit).Raw("ownerKey", "" + m_ownerKey).Bool("ownerIdentityMatches", true)
                .Raw("weapon", "" + di.Weapon).Str("skill", m_names[skill])
                .Str("liveSkill", liveSkill is null ? "" : liveSkill.m_id).Int("liveSkillType", liveSkill is null ? -1 : int(liveSkill.m_type))
                .Bool("attackerValid", attackerValid).Int("attackerUnit", attackerValid ? di.Attacker.m_unit.GetId() : 0)
                .Bool("attackerIsOwner", di.Attacker is player)
                .Int("damage", di.Damage).Int("damageDealt", di.DamageDealt).Int("crit", di.Crit)
                .Bool("dot", di.DoT).Bool("miss", di.Miss).Bool("trueStrike", di.TrueStrike).Bool("canKill", di.CanKill)
                .Raw("physical", "" + di.PhysicalDamage).Raw("fire", "" + di.FireDamage).Raw("ice", "" + di.IceDamage)
                .Raw("lightning", "" + di.LightningDamage).Raw("poison", "" + di.PoisonDamage).Raw("pure", "" + di.PureDamage)
                .Raw("target", QADamageTargetSnapshot(targetId));
            string row = j.Close();
            if (row.length() > 1500)
                m_dropped++;
            else
                m_rows.insertLast(row);
        }

        bool UpdateFrame(int ms) override
        {
            if (m_finished)
                return true;
            m_elapsed += ms;
            m_frames++;
            m_maxDt = max(m_maxDt, ms);
            if (!OwnerCurrent())
                Finish("aborted", "owner-class-actor-or-level-changed");
            else if (m_elapsed >= m_requested)
                Finish("complete", "native-window-ended");
            return m_finished;
        }
    }

    QADamageEventTask@ g_qaDamageEvents;

    // damageevents <tag> <ms> <skillIdCSV> <targetUnitIdCSV> | status | stop <tag>:
    // read-only native direct-hit hook receipts;1..8 unique live owned skills and
    //1..8 live Actors within1200px.100..30000ms,256 rows,4/part; explicit losses.
    // "stop" only detaches this QA observer; it never changes gameplay input.
    void VerbQADamageEvents(const string &in id, array<string>@ args)
    {
        if (args.length() == 1 && args[0] == "status")
        {
            Emit(Reply(id, true).Bool("active", g_qaDamageEvents !is null)
                .Str("tag", g_qaDamageEvents is null ? "" : g_qaDamageEvents.m_tag));
            return;
        }
        if (args.length() == 2 && args[0] == "stop")
        {
            if (g_qaDamageEvents is null || g_qaDamageEvents.m_tag != args[1])
            {
                Fail(id, "no matching active observer");
                return;
            }
            g_qaDamageEvents.Finish("aborted", "requested-stop");
            Emit(Reply(id, true).Bool("active", g_qaDamageEvents !is null));
            return;
        }
        auto plr = GetLocalPlayer();
        auto rec = GetLocalPlayerRecord();
        if (args.length() != 4 || plr is null || rec is null || !rec.local || rec.IsDead()
            || !plr.m_unit.IsValid() || plr.m_unit.IsDestroyed()
            || rec.playerClass is null || QueuedTasks::g_instance is null || g_qaDamageEvents !is null)
        {
            Fail(id, "needs live solo-local owner, task module, four arguments and no active observer");
            return;
        }
        int ms = int(parseInt(args[1]));
        auto names = args[2].split(",");
        auto targets = args[3].split(",");
        if (args[0].length() < 1 || args[0].length() > 64 || ms < 100 || ms > 30000
            || names.length() < 1 || names.length() > 8 || targets.length() < 1 || targets.length() > 8
            || plr.m_skills.length() > 128)
        {
            Fail(id, "invalid tag/window/filter bounds");
            return;
        }
        QADamageEventTask task;
        task.m_tag = args[0]; task.m_command = id; task.m_level = GetCurrentLevelFilename();
        task.m_class = rec.playerClass.m_id; task.m_ownerName = rec.name; task.m_ownerGuid = rec.id;
        task.m_ownerKey = rec.uniqueKey; task.m_ownerUnit = plr.m_unit.GetId();
        task.m_start = int(g_scene.GetTime()); task.m_startFrame = g_frames; task.m_requested = ms;
        Json ownerMeta;
        ownerMeta.Str("ownerClass", task.m_class).Str("ownerName", task.m_ownerName).Str("level", task.m_level);
        if (id.length() > 128 || ownerMeta.Close().length() > 800)
        {
            Fail(id, "owner metadata byte bound");
            return;
        }
        for (uint i = 0; i < names.length(); i++)
        {
            Skills::Skill@ found = null;
            int matches = 0;
            for (uint k = 0; k < plr.m_skills.length(); k++)
                if (plr.m_skills[k] !is null && plr.m_skills[k].m_id == names[i])
                {
                    @found = plr.m_skills[k];
                    matches++;
                }
            bool duplicate = false;
            for (uint k = 0; k < task.m_skills.length(); k++)
                if (found !is null && task.m_skills[k] == found.m_skillId)
                    duplicate = true;
            if (names[i].length() < 1 || names[i].length() > 128 || matches != 1 || found is null
                || found.m_skillId == 0 || duplicate)
            {
                Fail(id, "each selected ID must identify exactlyone distinct live owned Skill");
                return;
            }
            task.m_skills.insertLast(found.m_skillId); task.m_names.insertLast(found.m_id);
            Json j;
            task.m_skillRows.insertLast(j.Str("id", found.m_id).Raw("weapon", "" + found.m_skillId)
                .Int("type", int(found.m_type)).Int("matches", matches).Close());
        }
        for (uint i = 0; i < targets.length(); i++)
        {
            int targetId = int(parseInt(targets[i]));
            auto unit = g_scene.GetUnit(targetId);
            Actor@ actor = null;
            if (unit.IsValid() && !unit.IsDestroyed())
                @actor = cast<Actor>(unit.GetScriptBehavior());
            bool duplicate = false;
            for (uint k = 0; k < task.m_targets.length(); k++)
                if (task.m_targets[k] == targetId)
                    duplicate = true;
            if (targetId == 0 || "" + targetId != targets[i] || duplicate || actor is null || actor.IsDead()
                || unit == plr.m_unit || dist(xy(unit.GetPosition()), xy(plr.m_unit.GetPosition())) > 1200)
            {
                Fail(id, "distinct canonical signedUIDs must identify live foreign Actors within1200px");
                return;
            }
            task.m_targets.insertLast(targetId);
            task.m_initialTargets.insertLast(QADamageTargetSnapshot(targetId));
        }
        // Bound repeated headers before accepting. Together with four <=1500
        // byte rows/part and <=3000 byte terminal targets, this stays below the
        // protocol's native 15k line bound without silently clipping JSON.
        if (RawArray(task.m_initialTargets).length() + RawArray(task.m_skillRows).length() > 3000)
        {
            Fail(id, "selected metadata byte bound");
            return;
        }
        QueuedTasks::Queue(task);
        @g_qaDamageEvents = task;
        Emit(Reply(id, true).Str("tag", task.m_tag).Int("version", 1).Int("ms", ms)
            .Int("ownerUnit", task.m_ownerUnit).Raw("ownerKey", "" + task.m_ownerKey)
            .Str("ownerClass", task.m_class).Str("ownerName", task.m_ownerName).Str("level", task.m_level)
            .Int("start", task.m_start).Int("startFrame", task.m_startFrame)
            .Int("rowCap", QA_DAMAGE_EVENT_CAP).Int("chunk", QA_DAMAGE_EVENT_CHUNK)
            .Raw("skills", RawArray(task.m_skillRows)).Raw("initialTargets", RawArray(task.m_initialTargets)));
    }

    void Register_qa_damage_events()
    {
        RegisterVerb("damageevents", "<tag> <ms> <skillIdCSV> <targetUnitIdCSV> | status | stop <tag>", Verb(VerbQADamageEvents));
    }
}

