"""Strict collector for bounded native direct-hit receipts.

The callback HP precedes the current hit's NetDamage on the native Composite
path. Components/di.Damage/di.DamageDealt are distinct native primitives;
consumers must correlate an independently observed later HP debit. Pool DoT is
not included. This module neither sends input nor starts/stops the observer.
"""
import math
import time


def integer(value):
    return type(value) is int


def finite(value):
    return type(value) in (int, float) and math.isfinite(value)


def native_uint(value):
    if not integer(value) or not -(1 << 31) <= value <= (1 << 32)-1:
        return None
    return value & 0xffffffff


def snapshot_valid(row, initial=False):
    if not isinstance(row, dict) or not integer(row.get("unit")) or row["unit"] == 0:
        return False
    if row.get("valid") is not True:
        return not initial and row.get("valid") is False
    return (all(type(row.get(k)) is bool for k in ("dead", "composite"))
            and all(type(row.get(k)) is str and row[k] for k in ("name", "behavior"))
            and integer(row.get("hpMax")) and row["hpMax"] > 0
            and all(finite(row.get(k)) for k in ("hpFraction", "hpExact", "x", "y"))
            and (not initial or (row["dead"] is False and row["hpExact"] > 0)))


def damage_event_protocol(accepted, parts, *, require_complete=True):
    """Validate every retained part/row against the actual accepted filters.

    A complete zero-event window is valid as an observer result, never proof
    that a skill hit. Consumers must explicitly require their expected hits.
    """
    errors = []
    def need(condition, message):
        if not condition:
            errors.append(message)
    if not isinstance(accepted, dict) or not isinstance(parts, list):
        return {"valid": False, "errors": ["invalid protocol container"], "rows": []}
    need(accepted.get("ok") is True and integer(accepted.get("version")) and accepted["version"] == 1, "start rejected/version")
    need(type(accepted.get("tag")) is str and bool(accepted.get("tag")), "missing accepted tag")
    need(type(accepted.get("id")) is str and bool(accepted.get("id")), "missing accepted command")
    need(integer(accepted.get("ms")) and 100 <= accepted["ms"] <= 30000, "invalid requested window")
    need(integer(accepted.get("ownerUnit")) and accepted["ownerUnit"] != 0, "missing native owner")
    need(native_uint(accepted.get("ownerKey")) is not None, "missing native owner key")
    need(accepted.get("rowCap") == 256 and accepted.get("chunk") == 4, "unexpected bounds")
    need(all(type(accepted.get(k)) is str and accepted[k] for k in ("ownerClass", "ownerName", "level")),
         "missing native owner metadata")
    need(all(integer(accepted.get(k)) and accepted[k] >= 0 for k in ("start", "startFrame")), "missing native start clocks")
    skills = accepted.get("skills", [])
    targets = accepted.get("initialTargets", [])
    need(isinstance(skills, list) and 1 <= len(skills) <= 8, "missing bounded skills")
    need(isinstance(targets, list) and 1 <= len(targets) <= 8, "missing bounded targets")
    skill_map = {}
    if isinstance(skills, list):
        for s in skills:
            if not isinstance(s, dict):
                errors.append("malformed selected skill"); continue
            uid = native_uint(s.get("weapon"))
            need(uid not in (None, 0) and uid not in skill_map and integer(s.get("matches")) and s["matches"] == 1
                 and type(s.get("id")) is str and bool(s["id"]) and integer(s.get("type")), "ambiguous selected skill")
            if uid is not None:
                skill_map[uid] = s
    if errors:
        return {"valid": False, "errors": errors, "rows": []}
    target_ids = [t.get("unit") for t in targets if isinstance(t, dict)]
    if not all(integer(x) and x != 0 for x in target_ids):
        return {"valid": False, "errors": ["malformed selected target ID"], "rows": []}
    need(len(target_ids) == len(targets) and len(set(target_ids)) == len(target_ids)
         and all(snapshot_valid(t, True) for t in targets), "invalid initial target identity/HP")
    if not parts or not all(isinstance(p, dict) for p in parts):
        return {"valid": False, "errors": errors+["missing terminal parts"], "rows": []}
    first = parts[0]
    count = first.get("parts")
    need(integer(count) and 1 <= count <= 64, "invalid terminal part count")
    need(integer(first.get("stored")) and 0 <= first["stored"] <= 256, "invalid stored count")
    if errors:
        return {"valid": False, "errors": errors, "rows": []}
    need(len(parts) == count, "incomplete terminal parts")
    indices = [p.get("part") for p in parts]
    need(all(integer(i) for i in indices) and len(set(indices)) == len(indices), "duplicate/malformed parts")
    need(indices == list(range(len(parts))), "out-of-order/missing terminal parts")
    header = {k: v for k, v in first.items() if k not in ("part", "rows", "_t")}
    rows = []
    for p in parts:
        need({k: v for k, v in p.items() if k not in ("part", "rows", "_t")} == header, "inconsistent terminal header")
        chunk = p.get("rows")
        need(isinstance(chunk, list) and len(chunk) <= 4, "invalid terminal row chunk")
        if isinstance(chunk, list):
            rows.extend(chunk)
    if errors:
        return {"valid": False, "errors": errors, "rows": rows}
    stored = first.get("stored", -1)
    need(stored == len(rows), "stored/received row mismatch")
    if integer(stored) and stored >= 0:
        need(count == max(1, (stored+3)//4), "unexpected chunk count")
        need(all(len(p.get("rows", [])) == min(4, max(0, stored-4*i)) for i, p in enumerate(parts)), "short/overfull chunk")
    need(first.get("ev") == "damageevents" and integer(first.get("version")) and first["version"] == 1, "wrong terminal event")
    need(first.get("id") == accepted.get("id") and first.get("tag") == accepted.get("tag"), "foreign terminal identity")
    for k in ("ownerUnit", "ownerClass", "ownerName", "level", "start", "startFrame", "rowCap", "chunk", "skills", "initialTargets"):
        need(first.get(k) == accepted.get(k), "changed accepted header: "+k)
    need(native_uint(first.get("ownerKey")) == native_uint(accepted.get("ownerKey")), "changed owner key")
    need(first.get("detached") is True, "active gate not detached")
    need(first.get("state") in ("complete", "aborted") and type(first.get("reason")) is str, "invalid terminal state")
    need(type(first.get("truncated")) is bool and type(first.get("metadataLost")) is bool, "missing loss metadata")
    counters = ("hooks", "ownerHooks", "filteredOwner", "filteredSkill", "filteredTarget", "invalid", "accepted", "dropped", "elapsed", "frames", "maxDt", "end", "endFrame")
    need(all(integer(first.get(k)) and first[k] >= 0 for k in counters), "invalid native counters/clocks")
    if errors:
        return {"valid": False, "errors": errors, "rows": rows}
    if all(integer(first.get(k)) for k in counters):
        need(first["hooks"] == first["ownerHooks"]+first["filteredOwner"], "owner hook accounting")
        need(first["ownerHooks"] == first["invalid"]+first["filteredSkill"]+first["filteredTarget"]+first["accepted"], "filter accounting")
        need(first["accepted"] == stored+first["dropped"], "accepted/drop accounting")
        need(first["truncated"] == (first["dropped"] > 0 or first["metadataLost"]), "loss flag accounting")
    need(first.get("requested") == accepted.get("ms"), "changed requested duration")
    if require_complete:
        need(first.get("state") == "complete" and first.get("reason") == "native-window-ended", "incomplete native window")
        need(first.get("truncated") is False and first.get("metadataLost") is False
             and first.get("dropped") == 0 and first.get("invalid") == 0, "lost or invalid native events")
        if all(integer(first.get(k)) for k in ("elapsed", "maxDt", "end", "start", "frames", "endFrame", "startFrame")):
            dt = first["maxDt"]
            need(first["frames"] > 0 and 0 < dt <= 1000 and first["elapsed"] >= accepted.get("ms", 0), "native window did not finish")
            need(abs((first["end"]-first["start"])-first["elapsed"]) <= 2*dt, "inconsistent scene/elapsed clocks")
            need(first["end"]-first["start"] >= accepted.get("ms", 0)-dt, "censored native window")
            need(first["endFrame"] >= first["startFrame"], "native frame clock reversed")
    final = first.get("finalTargets", [])
    need(isinstance(final, list) and [x.get("unit") for x in final if isinstance(x, dict)] == target_ids
         and all(snapshot_valid(x) for x in final), "missing/foreign final targets")
    previous = None
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            errors.append("malformed native row"); continue
        need(integer(row.get("index")) and row["index"] == index, "lost/reordered accepted event")
        need(row.get("ownerUnit") == accepted.get("ownerUnit") and row.get("ownerIdentityMatches") is True
             and native_uint(row.get("ownerKey")) == native_uint(accepted.get("ownerKey")), "foreign row owner")
        uid = native_uint(row.get("weapon")); skill = skill_map.get(uid, {})
        need(bool(skill) and integer(row.get("liveSkillType")) and row.get("skill") == row.get("liveSkill") == skill.get("id")
             and row.get("liveSkillType") == skill.get("type"), "foreign/stale native skill")
        target = row.get("target", {})
        need(snapshot_valid(target) and target.get("valid") is True and target.get("unit") in target_ids, "foreign/missing row target")
        need(all(integer(row.get(k)) for k in ("now", "frame", "taskElapsed", "damage", "damageDealt", "crit", "physical", "fire", "ice", "lightning", "poison", "pure", "attackerUnit")), "malformed native row fields")
        need(all(type(row.get(k)) is bool for k in ("attackerValid", "attackerIsOwner", "dot", "miss", "trueStrike", "canKill")), "missing native flags")
        need(integer(row.get("damage")) and row["damage"] > 0
             and integer(row.get("damageDealt")) and 0 <= row["damageDealt"] <= row["damage"], "invalid positive-hook damage primitives")
        need(all(integer(row.get(k)) and 0 <= row[k] <= 0xffffffff
                 for k in ("physical", "fire", "ice", "lightning", "poison", "pure")), "invalid native unsigned component")
        need(integer(row.get("taskElapsed")) and 0 <= row["taskElapsed"] <= first["elapsed"], "event elapsed outside task window")
        if integer(row.get("now")) and integer(row.get("frame")):
            need(first.get("start", row["now"]+1) <= row["now"] <= first.get("end", row["now"]-1), "event outside native window")
            need(first.get("startFrame", row["frame"]+1) <= row["frame"] <= first.get("endFrame", row["frame"]-1), "event outside native frames")
            key = (row["now"], row["frame"])
            need(previous is None or all(key[i] >= previous[i] for i in (0, 1)), "native event clocks reversed")
            previous = key
