def collect_damage_events(g, accepted, tag, timeout=36, *, require_complete=True):
    """Wait on existing persistent GL receipts; never writes native state/input."""
    if not isinstance(accepted, dict) or accepted.get("ok") is not True:
        return damage_event_protocol(accepted, [], require_complete=require_complete)
    deadline = time.monotonic()+timeout
    first = g.wait_gl(lambda e: e.get("ev") == "damageevents" and e.get("tag") == tag and e.get("part") == 0,
                      timeout=timeout) or {}
    count = first.get("parts", 0)
    parts = []
    if integer(count) and 1 <= count <= 64:
        for index in range(count):
            remaining = deadline-time.monotonic()
            if remaining <= 0:
                break
            part = g.wait_gl(lambda e, i=index: e.get("ev") == "damageevents" and e.get("tag") == tag and e.get("part") == i,
                             timeout=remaining) or {}
            parts.append(part)
    result = damage_event_protocol(accepted, parts, require_complete=require_complete)
    if accepted.get("tag") != tag:
        result["errors"].append("requested collector tag differs from accepted tag")
        result["valid"] = False
    return result

